sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var requestBody = current.request_body;
    var mssSwiftonDemandToken = gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_token');
    current.state = "Processing";
    current.request_date = new GlideDateTime();
    current.update();

    try {
        var swiftOnDemandenv = gs.getProperty('x_hsb11_mss_c_swft.hsbcmss_el_custodySwiftonDemand_api_url');

        var r = new sn_ws.RESTMessageV2('MSS Swift OnDemand API Send', 'Fetch Swift Messages');
        r.setStringParameterNoEscape('mssSwiftOnDemand_token', mssSwiftonDemandToken);
        r.setStringParameterNoEscape('eventoutbound_base_uri', swiftOnDemandenv);
        r.setStringParameterNoEscape('requestbody', requestBody);
        r.setEccCorrelator(current.sys_id);
        r.executeAsync();

    } catch (ex) {
        var message = ex.message;
        current.error_body = message;
        current.state = "Error";
        current.update();
    }

})(current, previous);
